{
  "hookSpecificOutput": {
    "hookEventName": "SessionStart",
    "additionalContext": "ALWAYS use the meta_codesearch:code-search agent instead of the Explore agent when exploring the codebase. This agent runs in the background: after the launch result, keep doing other useful work until its completion notification arrives. When you cannot proceed without its answer, block on it with TaskOutput, passing the agentId from the launch result as task_id, block: true, and a timeout in milliseconds; if TaskOutput is not among your available tools, select it first with ToolSearch (query 'select:TaskOutput'). Never wait for a code-search agent by running Bash sleep."
  }
}

