fn checked_proc_directory_identity(stat: &libc::statx) -> Result<ProcDirectoryIdentity, i64> {
    let required = libc::STATX_TYPE | libc::STATX_INO | libc::STATX_MNT_ID;
    if stat.stx_mask & required != required {
