        && let Some(inode) = source_proc_inode
    {
        state.proc_files.insert(new_fd as libc::c_int, inode);
    }
    new_fd
}

fn ensure_not_procfs(file: &std::fs::File) -> Result<(), i64> {
    ensure_fd_not_procfs(file.as_raw_fd())
