12717	/// Deterministic inode for a normalized synthetic /proc path (FNV-1a). Stable
12718	/// across runs so `--verify` sees identical `stat` results.
12719	fn synthetic_proc_inode(path: &[u8]) -> u64 {
12720	    let mut hash: u64 = 0xcbf2_9ce4_8422_2325;
12721	    for byte in path {
12722	        hash ^= u64::from(*byte);
12723	        hash = hash.wrapping_mul(0x0000_0100_0000_01b3);
12724	    }
12725	    // Keep clear of low, conventionally-reserved inode numbers.
12726	    hash | 0x1000
12727	}
