12730	fn synthetic_proc_path_for_inode(inode: u64) -> Option<&'static [u8]> {
12731	    std::iter::once(b"/proc".as_slice())
12732	        .chain(SYNTHETIC_REGULAR_PROC_PATHS.iter().copied())
12733	        .find(|path| synthetic_proc_inode(path) == inode)
12734	}
